head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDFIL16202";

// [A] 초기 목록 미해결 — 같은 액션인데 method 가 2개다(poll#searchpoll vs poll#registerpollform) — 어느 것이 «열자마자» 인지 정할 근거가 없다

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil16202.onpageload' });
    }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_poolList_oncellclick
 * @description grd_poolList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_poolList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_poolList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_poolList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (r["questStatCd"] === '2') { await scwin.registerPoll(r["questNo"], r["questProgStatCd"]); return; }
        /* TODO Stage2: 행 동작 미정의: scwin.alert (열 ?) */ await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.alert'); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_poolList.oncellclick' });
    }
};

/**
 * @method
 * @name krxpage_pagenavigator_50_onclick
 * @description krxpage_pagenavigator_50 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_50_onclick = async function (index) {
    try {
        const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index;
        $c.util.getComponent('dma_SearchReq').set('pageIndex', pi);
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldfil16202.krxpage_pagenavigator_50_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Search
 * @description Search 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Search = async function (action) {
    const sbmOptions = {
        id: "tx_fn_Search",
        method: "post",
        action: action ?? "/support/poll.do",
        ref: "dma_SearchReq",
        target: "dlt_poolList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_RegisterPoll
 * @description Register Poll 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_RegisterPoll = async function (action) {
    const sbmOptions = {
        id: "tx_fn_RegisterPoll",
        method: "post",
        action: action ?? "/support/poll.do",
        ref: "dma_RegisterPollReq",
        target: "dlt_poolList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name grd_poolList_fmt_questTitle
 * @description grd pool List fmt quest Title 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_poolList_fmt_questTitle = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_poolList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "questStatCd") ?? '') : '');
        if (v === '2') { return '<a href="javascript:void(0)"' + (true ? ' class="lnk"' : '') + '>' + String((dl && dl.getCellData ? dl.getCellData(r, "questTitle") : '') ?? '') + '</a>'; }
        return '<a href="javascript:void(0)"' + (true ? ' class="lnk"' : '') + '>' + String((dl && dl.getCellData ? dl.getCellData(r, "questTitle") : '') ?? '') + '</a>';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_poolList.questTitle" }); return String(data ?? ''); }
};

/**
 * @method
 * @name grd_poolList_fmt_column5
 * @description grd pool List fmt column5 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_poolList_fmt_column5 = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_poolList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "questProgStatCd") ?? '') : '');
        if (v === '2') { return "작성완료"; }
        if (v === '1') { return "작성중"; }
        return "미작성";
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_poolList.column5" }); return String(data ?? ''); }
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    $c.util.getComponent('dma_SearchReq').set('method', 'searchPoll');
    await scwin.tx_fn_Search('poll.do');
};

/**
 * @method
 * @name registerPoll
 * @description register Poll 처리
 * @param {*} _questNo _questNo
 * @param {String} _questProgStatCd _questProgStatCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.registerPoll = async function (_questNo, _questProgStatCd) {
    $c.util.getComponent('dma_SearchReq').set('questNo', _questNo);
    $c.util.getComponent('dma_SearchReq').set('questProgStatCd', _questProgStatCd);
    $c.util.getComponent('dma_SearchReq').set('method', 'registerPollForm');
    const nr = await scwin.tx_fn_RegisterPoll('poll.do');
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/ui/jsp/JLDFIL16200.xml", { "questNo": _questNo, "questProgStatCd": _questProgStatCd, "method": 'registerPollForm' });
    }
};
